@Action
def match_intent(revised_user_query: str, second_intent_true:bool, language:str) -> str:
  # print(f"Revised User Query: {revised_user_query}")  # Log the query for debugging

  try:

    matches = flows.bell_Query_Rewriter.match_intent(revised_user_query).matches
    print(matches[0])
    if matches[0].intent:
      detected_intent = str(matches[0].intent.display_name)
      driver = detected_intent.split("_")[0] # Extract driver from intent name
      detected_intent = matches[0].intent.display_name
      confidence = matches[0].confidence
      print("confidence :", confidence)
      # print( f"driver {driver} and intent : {detected_intent}")
      if second_intent_true == True:
        if "en" in language.lower():
          respond(f"Ok let's address one question first")
        elif "fr" in language.lower():
          respond(f"D'accord, allons-y une question à la fois")
      parameters = {}
      entities = matches[0].parameters
      if entities:
        for entity in entities:
          parameters[entity] = entities[entity]
      parameters["route"] = detected_intent
      parameters["language"] = language
      parameters["utterance"] = revised_user_query
      parameters["second_intent_true"] = second_intent_true
      parameters["no_match_1"] = ""
      parameters["no_match_2"] = ""

      add_override(flows.bell_Query_Rewriter,parameters)

    else:
      parameters = {}
      parameters["route"] = "no_intent"
      parameters["language"] = language
      parameters["utterance"] = revised_user_query
      parameters["second_intent_true"] = second_intent_true
      ds_output= {}
      ds_output['answer'] = ""
      if (len(revised_user_query.split())<6) and ("page" in revised_user_query):
        pass
      else:
        if "en" in language.lower():
          ds_output = tools.en_generic_datastore.EN_Generic_Datastore({"query": revised_user_query})
        elif "fr" in language.lower():
          ds_output = tools.fr_generic_datastore.FR_Generic_Datastore({"query": revised_user_query})

      if ds_output['answer']:
        respond(ds_output['answer'])
        parameters["route"] = "infobot"
        add_override(flows.bell_Query_Rewriter,parameters)
      else:
        add_override(flows.bell_Query_Rewriter,parameters)

  except Exception as e:
    print(f"Error during intent matching: {e}")
    if "en" in language.lower():
      respond(f"An error occurred while processing your request, please try again") #Inform the user of the error
    elif "fr" in language.lower():
      respond(f"Une erreur est survenue, pouvez-vous réessayer") #Inform the user of the error

